/**
 * Loads public/isometric-art/manifest.json (generated by
 * scripts/build-isometric-art.ts) and resolves asset URLs. A missing or
 * invalid manifest is reported as an error result, never thrown at render
 * time: the caller then falls back to the map-accurate isometric view and
 * says why (src/app/view-mode.ts resolveIsometricVariant).
 */
import { isometricArtManifestSchema, type IsometricArtManifest } from './schema.ts';

export const ARTWORK_MANIFEST_URL = 'isometric-art/manifest.json';

export type ArtworkFetch = (url: string) => Promise<Pick<Response, 'ok' | 'status' | 'json'>>;

/** import.meta.env.BASE_URL under Vite; '/' elsewhere (Node, tests). */
function baseUrl(): string {
  const env = import.meta.env as { BASE_URL?: unknown } | undefined;
  const base = typeof env?.BASE_URL === 'string' && env.BASE_URL !== '' ? env.BASE_URL : '/';
  return base.endsWith('/') ? base : `${base}/`;
}

/** Absolute app URL of a manifest-relative file ('original/…', 'derived/…'). */
export function artworkUrl(relative: string, base: string = baseUrl()): string {
  return `${base}isometric-art/${relative}`;
}

export type ManifestLoadResult = { ok: true; manifest: IsometricArtManifest } | { ok: false; reason: string };

export const ARTWORK_UNAVAILABLE_REASON =
  'The campus illustration could not be loaded. Showing the map-accurate isometric view instead.';

export async function loadIsometricArtManifest(
  fetchImpl: ArtworkFetch = (u) => fetch(u),
  base: string = baseUrl(),
): Promise<ManifestLoadResult> {
  let body: unknown;
  try {
    const res = await fetchImpl(`${base}${ARTWORK_MANIFEST_URL}`);
    if (!res.ok) return { ok: false, reason: ARTWORK_UNAVAILABLE_REASON };
    body = await res.json();
  } catch {
    return { ok: false, reason: ARTWORK_UNAVAILABLE_REASON };
  }
  const parsed = isometricArtManifestSchema.safeParse(body);
  return parsed.success
    ? { ok: true, manifest: parsed.data }
    : { ok: false, reason: ARTWORK_UNAVAILABLE_REASON };
}
